UPDATE datasets SET validated=1 WHERE id='239aef0a043c4b76' AND (SELECT COUNT(*) FROM employees WHERE dataset_id='239aef0a043c4b76')=174 AND (SELECT COUNT(*) FROM courses WHERE dataset_id='239aef0a043c4b76')=10 AND (SELECT COUNT(*) FROM completions WHERE dataset_id='239aef0a043c4b76')=2860 AND (SELECT COUNT(*) FROM sessions WHERE dataset_id='239aef0a043c4b76')=34 AND (SELECT COUNT(*) FROM audit WHERE dataset_id='239aef0a043c4b76')=4427;
INSERT INTO active_dataset(singleton,dataset_id) SELECT 1,id FROM datasets WHERE id='239aef0a043c4b76' AND validated=1 ON CONFLICT(singleton) DO UPDATE SET dataset_id=excluded.dataset_id;
